BEGIN;
CREATE TABLE leagues (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, season integer NOT NULL, start_round integer NOT NULL CHECK(start_round BETWEEN 1 AND 38), end_round integer NOT NULL CHECK(end_round BETWEEN start_round AND 38), knockout_start integer NOT NULL CHECK(knockout_start BETWEEN start_round AND end_round), knockout_size integer NOT NULL CHECK(knockout_size IN (2,4,8,16,32)));
CREATE TABLE accounts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username text UNIQUE NOT NULL CHECK(username ~ '^[a-z0-9_]{3,32}$'), salt text NOT NULL, hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE teams (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, league_id bigint NOT NULL REFERENCES leagues(id), name text NOT NULL, manager text NOT NULL, external_id text, status text NOT NULL CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(league_id,name), UNIQUE(league_id,external_id), UNIQUE(league_id,id));
CREATE TABLE memberships (account_id bigint NOT NULL REFERENCES accounts(id), league_id bigint NOT NULL REFERENCES leagues(id), team_id bigint NOT NULL UNIQUE, PRIMARY KEY(account_id,league_id), FOREIGN KEY(league_id,team_id) REFERENCES teams(league_id,id));
CREATE TABLE scores (league_id bigint NOT NULL, team_id bigint NOT NULL, round integer NOT NULL CHECK(round BETWEEN 1 AND 38), points integer NOT NULL CHECK(points BETWEEN -100000 AND 100000), PRIMARY KEY(league_id,team_id,round), FOREIGN KEY(league_id,team_id) REFERENCES teams(league_id,id));
CREATE TABLE audit (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, league_id bigint REFERENCES leagues(id), action text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE leagues ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
